// import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { PageLayoutProps } from "./page-layout.types";
import type { CSSObject } from "@emotion/react";

import { TabBarClasses } from "@components/tab-bar";
import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";
import { VerticalTabBarClasses } from "@components/vertical-tab-bar";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "PageLayout";

// Generate child element class names for the component, should match available style slots
export const PageLayoutClasses = {
  root: "exp-textura_page-layout",
  skipToContent: "exp-textura_page-layout_skip_to_content",
  mainNav: "exp-textura_page-layout_main_nav",
  verticalTabBar: "exp-textura_page-layout_vertical_tab_bar",
  main: "exp-textura_page-layout_main",
  mainWidthDefault: "exp-textura_page-layout_main_default",
  header: "exp-textura_page-layout_header_title",
  body: "exp-textura_page-layout_body",
  bodyContent: "exp-textura_page-layout_body_content",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: PageLayoutProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<PageLayoutProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    // Root container acts as horizontal flex layout spanning viewport height
    display: "flex",
    flexDirection: "row",
    alignItems: "stretch",
    width: "100%",
    height: "100vh",
    overflow: "hidden",

    // Skip link anchor (hidden until focus)
    [`.${PageLayoutClasses.skipToContent}`]: {
      position: "absolute",
      top: 0,
      left: 0,
      transform: "translateY(-1200%)",
      background: theme.color.background.inverse,
      color: theme.color.content.inverseStrong,
      padding: `${theme.toRem(theme.spacing[8])} ${theme.toRem(theme.spacing[12])}`,
      zIndex: 100,
      textDecoration: "none",
      borderRadius: theme.toRem(theme.border.radius.sm),
      outline: `${theme.toRem(theme.border.width.sm)} solid transparent`,
      ":focus-visible": {
        transform: "translateY(0%)",
      },
      ...styleSlots?.skipToContent,
    },

    [`.${PageLayoutClasses.mainNav}`]: {
      display: "flex",
      flexDirection: "column",
      justifyContent: "stretch",
      height: "100vh",
      ...styleSlots?.mainNav,
    },

    [`.${PageLayoutClasses.verticalTabBar}`]: {
      display: "flex",
      flexDirection: "column",
      alignSelf: "stretch",
      width: "100%",
      flex: 1,
      [`.${VerticalTabBarClasses.panel}`]: {
        padding: 0,
        ...styleSlots?.verticalTabBarPanel,
      },
      ...styleSlots?.verticalTabBar,
    },

    [`.${PageLayoutClasses.main}`]: {
      display: "flex",
      flexDirection: "column",
      position: "relative",
      alignItems: "center",
      flex: 1,
      minWidth: 0,
      minHeight: 0,
      height: "100%",
      maxHeight: "100%",
      width: "100%",
      marginInline: "auto",
      overflow: "auto",
      padding: `${theme.toRem(theme.spacing[24])} 0 0`,
      ...styleSlots?.main,
    },

    [`.${PageLayoutClasses.mainWidthDefault}`]: {
      width: "100%",
      [`.${PageLayoutClasses.header}`]: {
        maxWidth: theme.layout.container.maxWidth.desktop,
        ...styleSlots?.mainWidthDefaultHeader,
      },
      [`.${PageLayoutClasses.bodyContent}`]: {
        maxWidth: theme.layout.container.maxWidth.desktop,
        ...styleSlots?.mainWidthDefaultBodyContent,
      },
      [`.${TabBarClasses.list}`]: {
        maxWidth: theme.layout.container.maxWidth.desktop,
        ...styleSlots?.mainWidthDefaultTabBarList,
      },
      [`.${TabBarClasses.panel}`]: {
        maxWidth: theme.layout.container.maxWidth.desktop,
        ...styleSlots?.mainWidthDefaultTabBarPanel,
      },
      [`@media (max-width: ${theme.toRem(theme.layout.container.maxWidth.tablet)})`]: {
        [`.${PageLayoutClasses.header}`]: { maxWidth: theme.layout.container.maxWidth.tablet },
        [`.${PageLayoutClasses.bodyContent}`]: { maxWidth: theme.layout.container.maxWidth.tablet },
        [`.${TabBarClasses.list}`]: { maxWidth: theme.layout.container.maxWidth.tablet },
        [`.${TabBarClasses.panel}`]: { maxWidth: theme.layout.container.maxWidth.tablet },
      },
      [`@media (max-width: ${theme.toRem(theme.layout.container.maxWidth.mobile)})`]: {
        [`.${PageLayoutClasses.header}`]: { maxWidth: theme.layout.container.maxWidth.mobile },
        [`.${PageLayoutClasses.bodyContent}`]: { maxWidth: theme.layout.container.maxWidth.mobile },
        [`.${TabBarClasses.list}`]: { maxWidth: theme.layout.container.maxWidth.mobile },
        [`.${TabBarClasses.panel}`]: { maxWidth: theme.layout.container.maxWidth.mobile },
      },
      ...styleSlots?.mainWidthDefault,
    },

    [`.${PageLayoutClasses.header}`]: {
      display: "flex",
      alignItems: "center",
      padding: `0 ${theme.toRem(theme.breakpoints.lg.horizontalMargin)}`,
      width: "100%",
      [`@media (max-width: ${theme.toRem(theme.layout.container.maxWidth.tablet)})`]: {
        padding: `0 ${theme.toRem(theme.breakpoints.md.horizontalMargin)}`,
      },
      [`@media (max-width: ${theme.toRem(theme.layout.container.maxWidth.mobile)})`]: {
        padding: `0 ${theme.toRem(theme.breakpoints.sm.horizontalMargin)}`,
      },
      ...styleSlots?.header,
    },

    [`.${PageLayoutClasses.body}`]: {
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      flex: 1,
      minHeight: 0,
      minWidth: 0,
      WebkitOverflowScrolling: "touch",
      width: "100%",
      ...styleSlots?.body,
    },

    [`.${PageLayoutClasses.bodyContent}`]: {
      display: "flex",
      flexDirection: "column",
      flex: 1,
      gap: theme.toRem("10px"),
      width: "100%",
      padding: `${theme.toRem(theme.spacing[24])} ${theme.toRem(theme.breakpoints.lg.horizontalMargin)}`,
      [`@media (max-width: ${theme.toRem(theme.layout.container.maxWidth.tablet)})`]: {
        padding: `${theme.toRem(theme.spacing[24])} ${theme.toRem(theme.breakpoints.md.horizontalMargin)}`,
      },
      [`@media (max-width: ${theme.toRem(theme.layout.container.maxWidth.mobile)})`]: {
        padding: `${theme.toRem(theme.spacing[24])} ${theme.toRem(theme.breakpoints.sm.horizontalMargin)}`,
      },
      ...styleSlots?.bodyContent,
    },

    [`.${TabBarClasses.root}`]: {
      paddingTop: theme.toRem(theme.spacing[24]),
      ...styleSlots?.tabBarRoot,
    },

    [`.${TabBarClasses.list}`]: {
      padding: `0 ${theme.toRem(theme.breakpoints.lg.horizontalMargin)}`,
      [`@media (max-width: ${theme.toRem(theme.layout.container.maxWidth.tablet)})`]: {
        padding: `0 ${theme.toRem(theme.breakpoints.md.horizontalMargin)}`,
      },
      [`@media (max-width: ${theme.toRem(theme.layout.container.maxWidth.mobile)})`]: {
        padding: `0 ${theme.toRem(theme.breakpoints.sm.horizontalMargin)}`,
      },
      ...styleSlots?.tabBarList,
    },

    [`.${TabBarClasses.panel}`]: {
      display: "flex",
      alignItems: "center",
      width: "100%",
      margin: "auto",
      ...styleSlots?.tabBarPanel,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledPageLayout = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<PageLayoutProps>((props) => generateStyles(props));
